using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using RoR2;
using RoR2.Audio;
using UnityEngine;
using UnityEngine.Networking;

public sealed class ClientCoinReturnObservation : MonoBehaviour {
 public bool disabled;public float fixedAtDisable,wallAtDisable;
 void OnDisable(){disabled=true;fixedAtDisable=Time.fixedTime;wallAtDisable=Time.realtimeSinceStartup;}
}

// Observes the original message handler, effect factory, coin Start and pooled timer.
public sealed partial class MovementBatchProbe {
 [Serializable] public class ClientCoinReport {
  public bool originalDefaultInitialized,sourceReady,handlerRegistered,received,spawned,burstsMatched,naturallyReturned,conserved,cleaned;
  public int messages,requestedCount,originalCount,effectIndex,budgetBefore,budgetAfter,poolCount,particlePeak;public int[] tierValues,burstCounts;public string factoryObservation;public string[] factoryInstances,burstModes;public float[] burstConstants,burstMinimums,burstMaximums,burstTimes;
