 }
 IEnumerator ProbeOriginalClientCoin(CharacterBody player){
  r.clientCoin=new ClientCoinReport{requestedCount=683,scope="Original transmitted message52/client effect factory, recovered CoinEmitter/CoinBehavior tier bursts and natural pooled timer return. Cosmetic diagnostic count683 does not grant money. One owned original VFX budget default is explicitly initialized/restored; full Console initialization is unproven. No interaction press/reward linkage/physical input/native audio/particle material parity or startup acceptance."};r.phase="original-client-coin-prepare";Save();
