  Check(r.clientCoin.sourceReady,"Original silent coin source/catalog/default budget contract changed");
  r.clientCoin.moneyBefore=player.master.money;r.clientCoin.xpBefore=TeamManager.instance.GetTeamExperience(TeamIndex.Player);CoinBehavior clone=null;EffectPool ownedPool=null;
  var medium=(RoR2.ConVar.IntConVar)RewardField(typeof(VFXBudget),"mediumPriorityCostThreshold").GetValue(null);r.clientCoin.mediumBefore=medium.GetString();r.clientCoin.mediumDeclared=medium.defaultValue;Check(r.clientCoin.mediumBefore=="0"&&r.clientCoin.mediumDeclared=="200","Original skipped budget/default contract changed");
