   activeBodyClient.RegisterHandler(52,msg=>{r.clientCoin.messages++;original(msg);var incoming=RewardField(typeof(EffectManager),"incomingEffectMessage").GetValue(null);var incomingType=incoming.GetType();var received=(EffectData)incomingType.GetField("effectData").GetValue(incoming);r.clientCoin.received=(EffectIndex)incomingType.GetField("effectIndex").GetValue(incoming)==effectIndex&&received.genericFloat==data.genericFloat&&Vector3.Distance(received.origin,data.origin)<.001f&&received.surfaceDefIndex==SurfaceDefIndex.Invalid&&received.networkSoundEventIndex==NetworkSoundEventIndex.Invalid;Check(r.clientCoin.received,"Original coin message decode mismatch");});r.clientCoin.handlerRegistered=activeBodyClient.handlers.ContainsKey(52);
   float began=Time.realtimeSinceStartup,fixedBegan=Time.fixedTime;int tickBegan=r.runClock.fixedTicks;EffectManager.SpawnEffect(prefab,data,true);Call(activeBodyClient,"Update");yield return null;yield return new WaitForEndOfFrame();Call(activeBodyClient,"Update");
   var allCoins=Resources.FindObjectsOfTypeAll<CoinBehavior>();var created=allCoins.Where(x=>x.gameObject.scene.IsValid()&&!baseline.Contains(x)).ToArray();var definition=EffectCatalog.GetEffectDef(effectIndex);r.clientCoin.factoryInstances=allCoins.Select(x=>x.name+"|scene="+x.gameObject.scene.IsValid()+"|active="+x.gameObject.activeInHierarchy+"|count="+x.originalCoinCount).ToArray();r.clientCoin.factoryObservation="created="+created.Length+"|definition="+(definition!=null&&definition.prefab==prefab)+"|cull="+(definition!=null&&definition.cullMethod!=null)+"|budget="+VFXBudget.totalCost+"|realCost="+VFXBudget.realTotalCost+"|mediumThreshold="+((RoR2.ConVar.IntConVar)RewardField(typeof(VFXBudget),"mediumPriorityCostThreshold").GetValue(null)).GetString()+"|pool="+pools.ContainsKey(prefab)+"|cache="+cache.ContainsKey(prefab)+"|client="+NetworkClient.active+"|disabled="+EffectManager.DisableAllEffectSpawning;Save();Check(r.clientCoin.messages==1&&r.clientCoin.received&&created.Length==1,"Original message/factory did not create one coin effect");clone=created[0];Check(pools.TryGetValue(prefab,out ownedPool),"Original coin pool missing");
   var actual=clone.GetComponent<EffectComponent>();var helper=clone.GetComponent<EffectManagerHelper>();var timer=clone.GetComponent<DestroyOnTimer>();var returned=clone.gameObject.AddComponent<ClientCoinReturnObservation>();r.clientCoin.originalCount=clone.originalCoinCount;
   r.clientCoin.spawned=clone.gameObject.activeInHierarchy&&clone.originalCoinCount==r.clientCoin.requestedCount&&actual.effectIndex==effectIndex&&actual.effectData.genericFloat==data.genericFloat&&Vector3.Distance(clone.transform.position,data.origin)<.001f&&helper&&helper.OwningPool==ownedPool&&ownedPool.InUseCount()==1&&timer.enabled&&timer.duration==sourceTimer.duration;Check(r.clientCoin.spawned,"Original coin Start/data/pool/timer identity mismatch");
   var expected=new[]{1,1,1,1,3};r.clientCoin.burstCounts=new int[expected.Length];r.clientCoin.burstModes=new string[expected.Length];r.clientCoin.burstConstants=new float[expected.Length];r.clientCoin.burstMinimums=new float[expected.Length];r.clientCoin.burstMaximums=new float[expected.Length];r.clientCoin.burstTimes=new float[expected.Length];for(int i=0;i<expected.Length;i++){var tier=clone.coinTiers[i];var emission=tier.particleSystem.emission;Check(tier.valuePerCoin==r.clientCoin.tierValues[i]&&emission.enabled&&emission.burstCount==1&&tier.particleSystem.gameObject.activeInHierarchy,"Original coin tier emission missing");var burst=emission.GetBurst(0);r.clientCoin.burstModes[i]=burst.count.mode.ToString();r.clientCoin.burstConstants[i]=burst.count.constant;r.clientCoin.burstMinimums[i]=burst.count.constantMin;r.clientCoin.burstMaximums[i]=burst.count.constantMax;r.clientCoin.burstTimes[i]=burst.time;r.clientCoin.burstCounts[i]=(int)burst.count.constant;Check(burst.time==0&&burst.count.mode==ParticleSystemCurveMode.Constant&&burst.count.constant==expected[i],"Original coin tier burst differs");}r.clientCoin.burstsMatched=r.clientCoin.burstCounts.SequenceEqual(expected);r.phase="original-client-coin-active";Save();
