   r.clientCoin.seconds=returned.wallAtDisable-began;r.clientCoin.fixedSeconds=returned.fixedAtDisable-fixedBegan;r.clientCoin.lastFixedSeconds=Time.fixedTime-fixedBegan;r.clientCoin.fixedTicks=r.runClock.fixedTicks-tickBegan;r.clientCoin.inUseAfter=ownedPool.InUseCount();r.clientCoin.returnedActive=clone.gameObject.activeInHierarchy;r.clientCoin.poolCount=ownedPool.PoolCount();r.clientCoin.naturallyReturned=returned.disabled&&clone&&!clone.gameObject.activeInHierarchy&&ownedPool.InUseCount()==0&&ownedPool.PoolCount()==1&&r.clientCoin.fixedSeconds>=sourceTimer.duration&&r.clientCoin.fixedSeconds<sourceTimer.duration+.05f&&Mathf.Abs(r.clientCoin.lastFixedSeconds-r.clientCoin.fixedTicks*Time.fixedDeltaTime)<.01f&&r.clientCoin.lastFixedSeconds>=r.clientCoin.fixedSeconds&&Mathf.Abs(r.clientCoin.seconds-r.clientCoin.fixedSeconds)<.3f&&r.clientCoin.peakAge>=sourceTimer.duration-.1f;Check(r.clientCoin.naturallyReturned,"Original coin timer did not naturally return pooled effect");
   r.clientCoin.moneyAfter=player.master.money;r.clientCoin.xpAfter=TeamManager.instance.GetTeamExperience(TeamIndex.Player);r.clientCoin.budgetAfter=VFXBudget.totalCost;r.clientCoin.conserved=r.clientCoin.messages==1&&r.clientCoin.moneyAfter==r.clientCoin.moneyBefore&&r.clientCoin.xpAfter==r.clientCoin.xpBefore&&r.clientCoin.budgetAfter==r.clientCoin.budgetBefore&&player.inventory.GetItemCountPermanent(RoR2Content.Items.Syringe)==1;Check(r.clientCoin.conserved,"Cosmetic coin effect changed funds/XP/item/budget");
  }finally{
   activeBodyClient.UnregisterHandler(52);if(pools.TryGetValue(prefab,out ownedPool)){foreach(var inUse in ownedPool.InUse.ToArray())ownedPool.ReturnObject(inUse);EffectManager.ClearPool(prefab);ownedPool.Kill();}cache.Remove(prefab);medium.AttemptSetString(r.clientCoin.mediumBefore);r.clientCoin.mediumRestored=medium.GetString();
  }
  yield return null;yield return null;r.clientCoin.cleaned=r.clientCoin.mediumRestored==r.clientCoin.mediumBefore&&medium.defaultValue==r.clientCoin.mediumDeclared&&!activeBodyClient.handlers.ContainsKey(52)&&!pools.ContainsKey(prefab)&&!cache.ContainsKey(prefab)&&!clone&&Resources.FindObjectsOfTypeAll<CoinBehavior>().Count(x=>x.gameObject.scene.IsValid())==baseline.Length&&VFXBudget.totalCost==r.clientCoin.budgetBefore;Check(r.clientCoin.cleaned,"Owned coin handler/pool/cache/effect cleanup incomplete");Save();
 }
}
